"""Pass 8: the single public question (pulse poll), ready for Simorgh's launch."""
from common import *
from d_review import addp, addl, N
KU = src('Kuran, Timur (1995)')
new('pulse-poll', T('نبضِ میز: تنها پرسشی که از مردم می‌پرسیم', 'The table\'s pulse: the one question we ask people'),
    T('ماهی یک بار، فقط یک پرسش: «دربارهٔ اینکه حکومتِ فعلی بماند یا تغییر کند، فکر می‌کنید چند درصدِ مردم مثلِ شما فکر می‌کنند؟» نه نظرِ کسی، فقط حدسش. با انتشارِ سیمرغ باز می‌شود؛ صفحه‌اش پرسش، قاعده‌های ایمنی، دلیلِ صادق‌بودن برای هر گروه، نتیجهٔ هر ماه و جدولِ تفسیر را دارد.',
      'Once a month, one question: what share of people do you think think like you about whether the current government should stay or change? Not anyone\'s view, only their estimate. Opens when Simorgh launches.'),
    [P('چرا این پرسش: بنا بر کوران، چیزی که سکوت را نگه می‌دارد خودِ ترجیح نیست، انتظار از دیگران است. این پرسش همان انتظار را می‌سنجد، و افشای فاصلهٔ آن با عددِ واقعی (حدود ۷۰٪ در پیمایشِ گمان) همان کاری است که پَرِ یکم را روشن نگه می‌دارد.', 'Why: per Kuran, silence is held by expectations, not preferences; the question measures that expectation, and revealing its gap from the real figure keeps feather one lit.', [KU, N['gam']]),
     P('چرا اتهام نمی‌سازد: پرسش حدس است نه نظر؛ هر گزینه را هر دو طرف می‌توانند بزنند. رأی‌گیری در جاهایی که رأی را به دیگران نشان نمی‌دهند: نظرسنجیِ کانالِ تلگرام (ناشناس حتی برای مدیرِ کانال)، نظرسنجیِ X، و فرمِ رمزگذاری‌شدهٔ CryptPad. فقط جمعِ هر ماه نگه داشته می‌شود.', 'Why it accuses no one: it is an estimate, not a view; both sides can pick any option. Votes are run where they are not shown to others; only monthly totals are kept.', [], True),
     P('بازیِ حدس با تعادلِ نش در راستگویی: جدولِ تفسیر علنی است، پس به‌جای پنهان‌کردنش بازی طوری ساخته شده که کم‌ضررترین حرکت برای هر گروه حدسِ راست باشد. سه قاعده: (۱) پیامِ منتشرشده ثابت است («این حدسِ شما بود، این عددِ مستقل است») و با نتیجه عوض نمی‌شود، پس دست‌کاری پیامی نمی‌خرد؛ (۲) بعد از هر پیمایشِ مستقل اعلام می‌شود چند درصد درست حدس زدند، پس تنها راهِ بُردن حدسِ واقعی است؛ (۳) در میانِ هزاران رأی هیچ رأیی تعیین‌کننده نیست، پس دروغ برای هیچ فردی سود ندارد. خطرِ باقی‌مانده رأیِ سازمان‌یافته است که مقایسهٔ تلگرام و X و قاعدهٔ «دو قله» آشکارش می‌کند.', 'A guessing game with a truth-telling Nash equilibrium: a fixed published message, a score for correct guesses against an independent figure, and no pivotal vote; organised voting is the remaining risk, exposed by cross-channel comparison.', [], True),
     P('پشتوانهٔ نظری: سازوکارهای «سازگار با انگیزه»، مثلِ قاعده‌های امتیازدهیِ درست برای پیش‌بینی و سرمِ حقیقتِ بیزیِ پرلک (۲۰۰۴)، که راستگویی را بهترین پاسخ می‌کنند. نسخهٔ ما ساده‌ترین شکل است: امتیاز در برابرِ عددی که رأی‌ها آن را نمی‌سازند.', 'Theory: incentive-compatible mechanisms such as proper scoring rules and Prelec\'s Bayesian truth serum (2004).', [], True),
     P('جدولِ تفسیر (خلاصه): بیشترِ رأی‌ها در ۵۰ تا ۷۵٪ یعنی تخمین به واقعیت نزدیک است؛ بیشتر از ۷۵٪ خوش‌بینی؛ ۲۵ تا ۵۰٪ نادانیِ جمعیِ ملایم؛ کمتر از ۲۵٪ نادانیِ جمعیِ کامل؛ دو قله یعنی دو تصویرِ جدا یا رأیِ سازمان‌یافته؛ پخش و برابر یعنی خلأ اطلاعاتی؛ کمتر از ۳۰۰ رأی یعنی نتیجه منتشر نمی‌شود. این جدول فقط برای تحلیل است؛ پیامِ منتشرشده همیشه یکی است.', 'Interpretation table in brief, with a ready follow-up message for each case.'),
     P('محدودیت: نتیجه نظرِ رأی‌دهندگان است نه همهٔ ایرانیان، و نمی‌دانیم هر رأی‌دهنده خودش کدام طرف است. ارزش در روندِ ماه‌به‌ماه است. پرسش در تلگرام و X جدا اجرا و جدا گزارش می‌شود؛ فاصلهٔ این دو خودش یافته است (داخل در برابرِ بیرون).', 'Limits: voters, not all Iranians; trend over months matters most; Telegram and X are reported separately.', [], True)],
    [L('simorgh:threshold-indicators', 'نشانگرهای آستانه', 'Threshold indicators'), L('simorgh:three-feathers', 'سه پَر', 'Three feathers'),
     L('soc:preference-falsification', 'نظریه: تحریفِ ترجیحات', 'Preference falsification'), L('simorgh:safety-first', 'اول ایمنی', 'Safety first')], 'simorgh:strategy')
addl('threshold-indicators', L('simorgh:pulse-poll', 'نبضِ میز: پرسشِ ماهانه', 'Pulse poll'))
addl('three-feathers', L('simorgh:pulse-poll', 'نبضِ میز: پرسشِ ماهانه', 'Pulse poll'))
addl('tools-directory', L('simorgh:pulse-poll', 'نبضِ میز (صفحهٔ poll)', 'Pulse poll page'))
addp('tools-directory', P('ابزارِ تازه در لایهٔ خصوصی: «نبضِ میز» (poll)، تنها پرسشِ ماهانه از مردم با جدولِ تفسیر؛ با انتشارِ سیمرغ باز می‌شود. و «نقشهٔ خرابی‌ها» در بخشِ روزِ بعد (ساخت ایران).', 'New private-layer tools: the pulse poll and the damage map.'))

new('poll-integrity', T('شمارشِ شفاف و بازیِ ضدِ تقلب', 'Transparent counting and the anti-cheating game'),
    T('هر کانال یا حسابی که پرسشِ «نبضِ میز» را اجرا می‌کند یک «ایالت» است: جدا شمرده می‌شود، روی نقشهٔ ایالت‌ها با رنگِ پرطرفدارترین گزینه و کم‌رنگیِ متناسب با اعتبار دیده می‌شود، و جمعِ کل با فرمولی علنی ساخته می‌شود. کنارش دفترِ تقلب است: هر حرکتِ تقلبیِ ممکن، ردی که در داده می‌گذارد و پاسخِ ما. دو ایجنت روی آن کار می‌کنند: قرمز حرکتِ بعدی را پیدا می‌کند، آبی خنثی‌اش می‌کند.',
      'Each channel running the poll is a "state": counted separately, shown on a state map coloured by its leading option and faded by credibility, combined by a public formula. Beside it, a cheating ledger of moves, traces and counters, worked on by a red and a blue agent.'),
    [P('وزنِ هر ایالت: اعتبار × رادیکالِ شمارِ رأی. اعتبار با هر پرچم ۰٫۳ کم می‌شود (کف ۰٫۱) و زیرِ ۳۰۰ رأی صفر است. رادیکال نمی‌گذارد یک ایالتِ خیلی بزرگ بقیه را ببلعد. این همان منطقِ وزن‌دهیِ نمونه است که پیمایش‌های جدی به کار می‌برند، با این تفاوت که این‌جا وزن به اعتبار بسته است نه به سن و جنس، چون از رأی‌دهنده هیچ داده‌ای نمی‌گیریم.', 'State weight = credibility × square root of votes; credibility drops 0.3 per flag (floor 0.1), zero under 300 votes.', [], True),
     P('سه نشانهٔ آماریِ تقلب، فقط از جمعِ رأی‌ها: (۱) هجومِ ناگهانی: یک ساعت بیش از ۳۵٪ کلِ رأی‌ها (شمارشِ ساعتی)؛ (۲) رأی‌های آخر با رأی‌های اول فرق دارند (فاصلهٔ دو توزیع بیش از ۰٫۲)، نشانهٔ بسیجِ یک گروه؛ (۳) ایالتی که با میانهٔ بقیه بیش از ۰٫۳ فاصله دارد، نشانهٔ تصاحب یا تفاوتِ واقعیِ مخاطب. هیچ ایالتی حذف نمی‌شود؛ فقط پرچم و وزنِ کمتر می‌گیرد و همه چیز نشان داده می‌شود.', 'Three statistical traces from totals only: hourly burst, early-late drift, divergence from the other states; nothing is deleted, only flagged and down-weighted.', [], True),
     P('دفترِ تقلب با نُه حرکتِ آغازین: ارتشِ ربات، بسیجِ گروهِ سازمان‌یافته، تصاحبِ کانال، نظرسنجیِ جعلی، جعلِ اسکرین‌شات، ترساندن، بی‌اعتبار کردنِ مرجع، خواستنِ نمایشِ رأی، تفسیرِ وارونه. هر کدام با ردش در داده و پاسخش. همهٔ قاعده‌ها علنی است، چون تقلبی که دیده شود دیگر کار نمی‌کند.', 'The ledger starts with nine moves, each with its trace and counter; all rules are public.')],
    [L('simorgh:pulse-poll', 'نبضِ میز', 'Pulse poll'), L('simorgh:pre-mortem', 'پیش‌مرگ', 'Pre-mortem'), L('soc:preference-falsification', 'بازیِ انتظار (کوران)', 'Expectations game')], 'simorgh:strategy')
addl('pulse-poll', L('simorgh:poll-integrity', 'شمارشِ شفاف و بازیِ ضدِ تقلب', 'Transparent counting'))
